package edu.portal.web;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import jakarta.validation.Valid; import org.springframework.validation.BindingResult; import java.util.*;
@Controller public class PortalController { private final JdbcPortalRepository repo; public PortalController(JdbcPortalRepository repo){this.repo=repo;}
 @GetMapping("/") String home(Model m){m.addAttribute("students",repo.count("student"));m.addAttribute("companies",repo.count("company"));m.addAttribute("vacancies",repo.report("v_vacancy_application_counts").stream().filter(x->"OPEN".equals(x.get("status"))).count());m.addAttribute("applications",repo.count("application"));m.addAttribute("selections",repo.report("v_company_recruitment_summary").stream().mapToLong(x->((Number)x.get("selections")).longValue()).sum());return "home";}
 @GetMapping("/students") String students(@RequestParam(defaultValue="")String q,Model m){m.addAttribute("rows",repo.students(q));m.addAttribute("q",q);return "students";} @GetMapping("/students/new") String newStudent(Model m){m.addAttribute("student",new StudentForm());m.addAttribute("departments",repo.departments());return "student-form";}
 @PostMapping("/students") String save(@Valid @ModelAttribute("student") StudentForm f,BindingResult r,Model m,RedirectAttributes flash){if(r.hasErrors()){m.addAttribute("departments",repo.departments());return "student-form";}repo.saveStudent(f);flash.addFlashAttribute("success","Student saved.");return "redirect:/students";} @GetMapping("/students/{id}/edit") String edit(@PathVariable int id,Model m){Map<String,Object>x=repo.student(id);StudentForm f=new StudentForm();f.studentId=id;f.name=(String)x.get("name");f.departmentId=((Number)x.get("department_id")).intValue();f.qualification=(String)x.get("qualification");f.skills=(String)x.get("skills");f.cgpa=((Number)x.get("cgpa")).doubleValue();f.email=(String)x.get("email");f.phone=(String)x.get("phone");m.addAttribute("student",f);m.addAttribute("departments",repo.departments());return "student-form";} @PostMapping("/students/{id}/delete") String delete(@PathVariable int id,RedirectAttributes f){repo.deleteStudent(id);f.addFlashAttribute("success","Student deleted.");return "redirect:/students";}
 @GetMapping("/companies") String companies(Model m){m.addAttribute("rows",repo.companies());return "companies";} @GetMapping("/companies/new")String newCompany(Model m){m.addAttribute("company",new CompanyForm());return "company-form";} @PostMapping("/companies")String saveCompany(@Valid @ModelAttribute("company")CompanyForm c,BindingResult r,RedirectAttributes f){if(r.hasErrors())return "company-form";repo.saveCompany(c);f.addFlashAttribute("success","Company saved.");return "redirect:/companies";} @GetMapping("/companies/{id}/edit")String editCompany(@PathVariable int id,Model m){var x=repo.company(id);var c=new CompanyForm();c.companyId=id;c.name=(String)x.get("name");c.industry=(String)x.get("industry");c.location=(String)x.get("location");c.contact=(String)x.get("contact");m.addAttribute("company",c);return "company-form";} @PostMapping("/companies/{id}/delete")String deleteCompany(@PathVariable int id,RedirectAttributes f){repo.deleteCompany(id);f.addFlashAttribute("success","Company deleted.");return "redirect:/companies";}
 @GetMapping("/vacancies") String vacancies(@RequestParam(defaultValue="")String company,@RequestParam(defaultValue="")String location,@RequestParam(defaultValue="")String department,Model m){var rows=repo.vacancies().stream().filter(v->company.isBlank()||String.valueOf(v.get("company_id")).equals(company)).filter(v->location.isBlank()||String.valueOf(v.get("location")).equalsIgnoreCase(location)).toList();m.addAttribute("rows",rows);m.addAttribute("companies",repo.companies());m.addAttribute("departments",repo.departments());return "vacancies";}
 @GetMapping("/apply") String apply(Model m){m.addAttribute("students",repo.students(""));m.addAttribute("vacancies",repo.vacancies());return "apply";} @PostMapping("/apply") String doApply(@RequestParam int studentId,@RequestParam int vacancyId,RedirectAttributes f){repo.apply(studentId,vacancyId);f.addFlashAttribute("success","Application submitted.");return "redirect:/applications";}
 @GetMapping("/applications") String applications(@RequestParam(defaultValue="")String status,Model m){m.addAttribute("rows",repo.applications(status));m.addAttribute("status",status);return "applications";} @PostMapping("/applications/{id}/status") String status(@PathVariable int id,@RequestParam String target,RedirectAttributes f){repo.status(id,target);f.addFlashAttribute("success","Status updated.");return "redirect:/applications";}
 @GetMapping("/reports") String reports(Model m){m.addAttribute("companies",repo.report("v_company_recruitment_summary"));m.addAttribute("departments",repo.report("v_department_placement_stats"));m.addAttribute("vacancies",repo.report("v_vacancy_application_counts"));return "reports";}
}
